mapper.select:
select id, event_id, event_type, user_id, order_id, product_code, event_published, publish_status, base_quota, create_time, update_time
from benefit_event
where event_type = #{eventType}
  and event_published = 0
  and (publish_status in ('PENDING', 'RETRY')
       or (publish_status = 'PROCESSING' and update_time < date_sub(now(), interval 5 minute)))

    and create_time >= #{since}


    and id > #{lastId}

order by id asc
limit #{pageSize}
